import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios'; // Make sure axios is imported

const LoginPage = () => {
  const navigate = useNavigate();

  // State to hold the username (email) and password
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(''); // NEW: State to hold any login error messages
  const [isLoading, setIsLoading] = useState(false); // NEW: State to manage loading during API call

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError(''); // Clear any previous errors
    setIsLoading(true); // Show a loading state on the button

    try {
      // --- THIS IS THE REAL API CALL ---
      // We send a POST request to the backend's login endpoint.
      // Note: Django's default user model uses 'username', not 'email', for login.
      const response = await axios.post('http://127.0.0.1:8000/api/auth/login/', {
        username: username,
        password: password,
      });

      // --- HANDLE SUCCESS ---
      console.log("Login successful:", response.data);

      // 1. Get the token from the response.
      const token = response.data.token;

      // 2. Save the token to the browser's localStorage.
      // localStorage is a simple way to store data that persists even after the browser is closed.
      localStorage.setItem('authToken', token);

      // 3. Set up axios to automatically send this token in the header of all future requests.
      axios.defaults.headers.common['Authorization'] = `Token ${token}`;

      // 4. Redirect the user to the dashboard.
      navigate('/dashboard');

    } catch (err) {
      // --- HANDLE FAILURE ---
      console.error("Login failed:", err.response);
      setError('Invalid username or password. Please try again.'); // Set a user-friendly error message
    } finally {
      setIsLoading(false); // Hide the loading state
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-background-light dark:bg-background-dark">
      <div className="w-full max-w-md p-8 space-y-8 bg-card-light dark:bg-card-dark rounded-lg shadow-lg">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-text-light dark:text-text-dark">
            University HRMS Portal
          </h2>
        </div>
        <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
          {/* --- NEW: ERROR MESSAGE DISPLAY --- */}
          {error && (
            <div className="p-3 bg-red-100 text-red-700 rounded-md text-sm">
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div>
              <label htmlFor="username" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark">
                Username
              </label>
              <div className="mt-1">
                <input
                  id="username"
                  name="username"
                  type="text"
                  autoComplete="username"
                  required
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full px-3 py-2 border rounded-md"
                  placeholder="Enter your admin username"
                />
              </div>
            </div>
            <div>
              <label htmlFor="password" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark">
                Password
              </label>
              <div className="mt-1">
                <input
                  id="password"
                  name="password"
                  type="password"
                  autoComplete="current-password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.g.et.value)}
                  className="w-full px-3 py-2 border rounded-md"
                  placeholder="••••••••"
                />
              </div>
            </div>
          </div>

          <div>
            <button
              type="submit"
              disabled={isLoading}
              className="w-full flex justify-center py-2 px-4 border rounded-md shadow-sm text-sm font-medium text-white bg-primary hover:bg-blue-600 disabled:bg-gray-400"
            >
              {isLoading ? 'Signing In...' : 'Sign in'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginPage;
